import React, { useState, useEffect } from "react";
import {
  Container,
  Typography,
  AppBar,
  Toolbar,
  CssBaseline,
  ThemeProvider,
  createTheme,
  Box,
  Grid,
  Fab,
  Card,
  CardContent,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  MenuItem,
  Chip,
  LinearProgress,
  Select,
  FormControl,
  InputLabel,
  Alert,
  CardMedia,
  IconButton,
} from "@mui/material";

import {
  Restaurant as RestaurantIcon,
  Add as AddIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  CheckCircle as CheckIcon,
  LocalFireDepartment as FireIcon,
  Remove as RemoveIcon,
  Add as AddQuantityIcon,
} from "@mui/icons-material";

import axios from "axios";

import AuthPage from "./components/AuthPage";
import UserDashboard from "./components/UserDashboard";
import StaffDashboard from "./components/StaffDashboard";
import AdminDashboard from "./components/AdminDashboard";

/* =========================================================
   THEME
========================================================= */

const theme = createTheme({
  palette: {
    primary: {
      main: "#2E7D32",
    },
    secondary: {
      main: "#FF9800",
    },
  },
});

/* =========================================================
   MENU ITEMS
========================================================= */

const menuItems = [
  {
    name: "Masala Dosa",
    price: 80,
    category: "Breakfast",
    image:
      "https://images.unsplash.com/photo-1631452180519-c014fe946bc7?w=400&h=300&fit=crop",
    preparationTime: 10,
  },
  {
    name: "Butter Chicken",
    price: 220,
    category: "Lunch",
    image:
      "https://images.unsplash.com/photo-1565557623262-b51c2513a641?w=400&h=300&fit=crop",
    preparationTime: 25,
  },
  {
    name: "Biryani",
    price: 180,
    category: "Lunch",
    image:
      "https://www.awesomecuisine.com/wp-content/uploads/2008/03/Vegetable-Biryani.jpg",
    preparationTime: 20,
  },
  {
    name: "Paneer Tikka",
    price: 160,
    category: "Dinner",
    image:
      "https://images.unsplash.com/photo-1599487488170-d11ec9c172f0?w=400&h=300&fit=crop",
    preparationTime: 15,
  },
  {
    name: "Samosa",
    price: 40,
    category: "Snacks",
    image:
      "https://images.unsplash.com/photo-1601050690597-df0568f70950?w=400&h=300&fit=crop",
    preparationTime: 8,
  },
  {
    name: "Chai",
    price: 20,
    category: "Beverages",
    image:
      "https://images.unsplash.com/photo-1571934811356-5cc061b6821f?w=400&h=300&fit=crop",
    preparationTime: 5,
  },
  {
    name: "Gulab Jamun",
    price: 60,
    category: "Desserts",
    image:
      "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRqa3gLqniZ1W-aHtjbpwMQ_z2aovluPJ6XKA&s",
    preparationTime: 3,
  },
  {
    name: "Noodles",
    price: 120,
    category: "Lunch",
    image:
      "https://shwetainthekitchen.com/wp-content/uploads/2023/03/vegetable-noodles.jpg",
    preparationTime: 12,
  },
  {
    name: "Pizza",
    price: 200,
    category: "Dinner",
    image:
      "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRknofa_9Vpomis8CZcooxiIe6afdQnVB6HXw&s",
    preparationTime: 18,
  },
  {
    name: "Burger",
    price: 150,
    category: "Snacks",
    image:
      "https://images.unsplash.com/photo-1568901346375-23c9450c58cd?w=400&h=300&fit=crop",
    preparationTime: 10,
  },
  {
    name: "Sandwich",
    price: 90,
    category: "Breakfast",
    image:
      "https://images.unsplash.com/photo-1553909489-cd47e0907980?w=400&h=300&fit=crop",
    preparationTime: 7,
  },
  {
    name: "Salad",
    price: 110,
    category: "Lunch",
    image:
      "https://images.unsplash.com/photo-1540420773420-3366772f4999?w=400&h=300&fit=crop",
    preparationTime: 5,
  },
];

/* =========================================================
   TOKEN CARD
========================================================= */

const TokenCard = ({
  token,
  onEdit,
  onDelete,
  onStatusUpdate,
}) => {
  const getStatusColor = (status) => {
    const colors = {
      Pending: "#FF9800",
      Preparing: "#2196F3",
      Ready: "#9C27B0",
      Served: "#4CAF50",
      Cancelled: "#F44336",
    };

    return colors[status] || "#757575";
  };

  const getStatusIcon = (status) => {
    const icons = {
      Pending: "⏳",
      Preparing: "👨‍🍳",
      Ready: "🔔",
      Served: "✅",
      Cancelled: "❌",
    };

    return icons[status] || "⏳";
  };

  const total = Number(token.price || 0) * Number(token.quantity || 1);

  return (
    <Card
      sx={{
        borderRadius: 3,
        boxShadow: "0 8px 25px rgba(0,0,0,0.1)",
        height: "100%",
        transition: "all 0.3s ease",
        "&:hover": {
          transform: "translateY(-5px)",
          boxShadow: "0 12px 35px rgba(0,0,0,0.15)",
        },
      }}
    >
      <CardMedia
        component="img"
        height="160"
        image={token.image}
        alt={token.itemName}
        sx={{
          objectFit: "cover",
          borderBottom: "3px solid #2E7D32",
        }}
      />

      <CardContent sx={{ p: 2 }}>
        <Box
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "flex-start",
            mb: 2,
            gap: 1,
          }}
        >
          <Typography
            variant="h6"
            component="h2"
            sx={{
              fontWeight: 700,
              background:
                "linear-gradient(135deg, #2E7D32, #4CAF50)",
              backgroundClip: "text",
              WebkitBackgroundClip: "text",
              color: "transparent",
            }}
          >
            {token.itemName}
          </Typography>

          <Chip
            icon={<span>{getStatusIcon(token.status)}</span>}
            label={token.status}
            size="small"
            sx={{
              background: `linear-gradient(135deg, ${getStatusColor(
                token.status
              )}, ${getStatusColor(token.status)}80)`,
              color: "white",
              fontWeight: 700,
              fontSize: "0.75rem",
            }}
          />
        </Box>

        <Box
          sx={{
            display: "flex",
            gap: 1,
            mb: 2,
            flexWrap: "wrap",
          }}
        >
          <Chip
            label={token.category}
            size="small"
            variant="outlined"
            sx={{
              borderColor: "#2E7D32",
              color: "#2E7D32",
              fontWeight: 600,
            }}
          />

          <Chip
            label={`Qty: ${token.quantity}`}
            size="small"
            sx={{
              background:
                "linear-gradient(135deg, #FF9800, #FFB74D)",
              color: "white",
              fontWeight: 600,
            }}
          />
        </Box>

        <Box
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            mb: 2,
          }}
        >
          <Typography
            variant="body2"
            color="text.secondary"
            sx={{ fontWeight: 600 }}
          >
            👤 {token.customerName}
          </Typography>

          <Typography
            variant="body2"
            color="text.secondary"
            sx={{ fontWeight: 600 }}
          >
            ⏱️ {token.preparationTime} min
          </Typography>
        </Box>

        <Box
          sx={{
            textAlign: "center",
            p: 1,
            background:
              "linear-gradient(135deg, #E8F5E8, #F1F8E9)",
            borderRadius: 2,
            mb: 2,
          }}
        >
          <Typography
            variant="h5"
            sx={{
              fontWeight: 800,
              color: "#2E7D32",
            }}
          >
            ₹{total}
          </Typography>

          <Typography
            variant="caption"
            sx={{
              color: "#4CAF50",
              fontWeight: 600,
            }}
          >
            (₹{token.price} × {token.quantity})
          </Typography>
        </Box>

        {token.createdAt && (
          <Typography
            variant="caption"
            color="text.secondary"
            sx={{
              display: "block",
              textAlign: "center",
              fontWeight: 600,
            }}
          >
            🕒{" "}
            {new Date(token.createdAt).toLocaleTimeString()}
          </Typography>
        )}

        {token.specialInstructions && (
          <Typography
            variant="caption"
            color="text.secondary"
            sx={{
              display: "block",
              mt: 1,
              fontStyle: "italic",
              textAlign: "center",
            }}
          >
            📝 {token.specialInstructions}
          </Typography>
        )}
      </CardContent>

      <Box
        sx={{
          p: 2,
          display: "flex",
          gap: 1,
          justifyContent: "center",
          flexWrap: "wrap",
        }}
      >
        {token.status === "Pending" && (
          <Button
            size="small"
            startIcon={<FireIcon />}
            onClick={() =>
              onStatusUpdate(token._id, "Preparing")
            }
            variant="contained"
            color="warning"
            sx={{ borderRadius: 2 }}
          >
            Start Cooking
          </Button>
        )}

        {token.status === "Preparing" && (
          <Button
            size="small"
            startIcon={<CheckIcon />}
            onClick={() =>
              onStatusUpdate(token._id, "Ready")
            }
            variant="contained"
            color="secondary"
            sx={{ borderRadius: 2 }}
          >
            Mark Ready
          </Button>
        )}

        {token.status === "Ready" && (
          <Button
            size="small"
            startIcon={<CheckIcon />}
            onClick={() =>
              onStatusUpdate(token._id, "Served")
            }
            variant="contained"
            color="success"
            sx={{ borderRadius: 2 }}
          >
            Mark Served
          </Button>
        )}

        <Button
          size="small"
          startIcon={<EditIcon />}
          onClick={() => onEdit(token)}
          variant="outlined"
          sx={{ borderRadius: 2 }}
        >
          Edit
        </Button>

        <Button
          size="small"
          startIcon={<DeleteIcon />}
          onClick={() => onDelete(token._id)}
          variant="outlined"
          color="error"
          sx={{ borderRadius: 2 }}
        >
          Delete
        </Button>
      </Box>
    </Card>
  );
};

/* =========================================================
   TOKEN FORM
========================================================= */

const TokenForm = ({
  open,
  token,
  onCreate,
  onUpdate,
  onClose,
}) => {
  const [formData, setFormData] = useState({
    itemName: "",
    price: "",
    category: "",
    status: "Pending",
    customerName: "Walk-in Customer",
    quantity: 1,
    specialInstructions: "",
    preparationTime: 15,
    image: "",
  });

  const [selectedMenuItem, setSelectedMenuItem] =
    useState(null);

  useEffect(() => {
    if (!open) return;

    if (token) {
      setFormData({
        itemName: token.itemName || "",
        price: token.price || "",
        category: token.category || "",
        status: token.status || "Pending",
        customerName:
          token.customerName || "Walk-in Customer",
        quantity: token.quantity || 1,
        specialInstructions:
          token.specialInstructions || "",
        preparationTime: token.preparationTime || 15,
        image: token.image || "",
      });

      const menuItem = menuItems.find(
        (item) => item.name === token.itemName
      );

      setSelectedMenuItem(menuItem || null);
    } else {
      setFormData({
        itemName: "",
        price: "",
        category: "",
        status: "Pending",
        customerName: "Walk-in Customer",
        quantity: 1,
        specialInstructions: "",
        preparationTime: 15,
        image: "",
      });

      setSelectedMenuItem(null);
    }
  }, [token, open]);

  const handleMenuItemSelect = (itemName) => {
    const selectedItem = menuItems.find(
      (item) => item.name === itemName
    );

    setSelectedMenuItem(selectedItem || null);

    if (selectedItem) {
      setFormData((prev) => ({
        ...prev,
        itemName: selectedItem.name,
        price: selectedItem.price,
        category: selectedItem.category,
        preparationTime: selectedItem.preparationTime,
        image: selectedItem.image,
      }));
    }
  };

  const handleQuantityChange = (change) => {
    const newQuantity = Math.max(
      1,
      Number(formData.quantity) + change
    );

    setFormData((prev) => ({
      ...prev,
      quantity: newQuantity,
    }));
  };

  const handleChange = (event) => {
    const { name, value } = event.target;

    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSubmit = (event) => {
    event.preventDefault();

    if (!formData.itemName) {
      return;
    }

    const tokenData = {
      ...formData,
      price: parseFloat(formData.price),
      quantity: parseInt(formData.quantity, 10),
      preparationTime: parseInt(
        formData.preparationTime,
        10
      ),
    };

    if (token) {
      onUpdate(token._id, tokenData);
    } else {
      onCreate(tokenData);
    }
  };

  const totalPrice =
    (Number(formData.price) || 0) *
    (Number(formData.quantity) || 1);

  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="md"
      fullWidth
      PaperProps={{
        sx: {
          borderRadius: 3,
          background:
            "linear-gradient(135deg, #ffffff 0%, #f8f9fa 100%)",
        },
      }}
    >
      <DialogTitle
        sx={{
          background:
            "linear-gradient(135deg, #2E7D32 0%, #4CAF50 100%)",
          color: "white",
          textAlign: "center",
          fontWeight: 700,
        }}
      >
        {token
          ? "✏️ Edit Food Order"
          : "🍽️ Create New Food Order"}
      </DialogTitle>

      <DialogContent sx={{ mt: 2 }}>
        <form onSubmit={handleSubmit}>
          <Grid container spacing={3}>
            {/* Food selection */}
            <Grid item xs={12}>
              <FormControl fullWidth>
                <InputLabel>Select Food Item</InputLabel>

                <Select
                  value={formData.itemName}
                  onChange={(event) =>
                    handleMenuItemSelect(
                      event.target.value
                    )
                  }
                  label="Select Food Item"
                  required
                >
                  {menuItems.map((item) => (
                    <MenuItem
                      key={item.name}
                      value={item.name}
                    >
                      <Box
                        sx={{
                          display: "flex",
                          alignItems: "center",
                          width: "100%",
                        }}
                      >
                        <img
                          src={item.image}
                          alt={item.name}
                          style={{
                            width: 40,
                            height: 40,
                            borderRadius: 4,
                            marginRight: 12,
                            objectFit: "cover",
                          }}
                        />

                        <Box sx={{ flexGrow: 1 }}>
                          <Typography
                            variant="body1"
                            fontWeight="600"
                          >
                            {item.name}
                          </Typography>

                          <Typography
                            variant="caption"
                            color="text.secondary"
                          >
                            {item.category} • ₹
                            {item.price} •{" "}
                            {item.preparationTime} min
                          </Typography>
                        </Box>
                      </Box>
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>

            {/* Preview */}
            {selectedMenuItem && (
              <Grid item xs={12}>
                <Alert
                  severity="info"
                  sx={{ borderRadius: 2 }}
                >
                  <Box
                    sx={{
                      display: "flex",
                      alignItems: "center",
                    }}
                  >
                    <img
                      src={selectedMenuItem.image}
                      alt={selectedMenuItem.name}
                      style={{
                        width: 60,
                        height: 60,
                        borderRadius: 8,
                        marginRight: 12,
                        objectFit: "cover",
                      }}
                    />

                    <Box>
                      <Typography fontWeight="600">
                        {selectedMenuItem.name}
                      </Typography>

                      <Typography variant="body2">
                        {selectedMenuItem.category} •{" "}
                        {selectedMenuItem.preparationTime}{" "}
                        min preparation
                      </Typography>
                    </Box>
                  </Box>
                </Alert>
              </Grid>
            )}

            {/* Price */}
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Unit Price (₹)"
                name="price"
                value={formData.price}
                InputProps={{ readOnly: true }}
                sx={{ backgroundColor: "#f5f5f5" }}
              />
            </Grid>

            {/* Quantity */}
            <Grid item xs={12} sm={6}>
              <Typography
                variant="body2"
                gutterBottom
                sx={{ fontWeight: 600 }}
              >
                Quantity
              </Typography>

              <Box
                sx={{
                  display: "flex",
                  alignItems: "center",
                  gap: 1,
                }}
              >
                <IconButton
                  onClick={() =>
                    handleQuantityChange(-1)
                  }
                  sx={{
                    backgroundColor: "#FF9800",
                    color: "white",
                    "&:hover": {
                      backgroundColor: "#F57C00",
                    },
                  }}
                >
                  <RemoveIcon />
                </IconButton>

                <TextField
                  value={formData.quantity}
                  InputProps={{ readOnly: true }}
                  sx={{
                    width: 80,
                    "& .MuiInputBase-input": {
                      textAlign: "center",
                      fontWeight: 700,
                    },
                  }}
                />

                <IconButton
                  onClick={() =>
                    handleQuantityChange(1)
                  }
                  sx={{
                    backgroundColor: "#4CAF50",
                    color: "white",
                    "&:hover": {
                      backgroundColor: "#2E7D32",
                    },
                  }}
                >
                  <AddQuantityIcon />
                </IconButton>
              </Box>
            </Grid>

            {/* Customer */}
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Customer Name"
                name="customerName"
                value={formData.customerName}
                onChange={handleChange}
              />
            </Grid>

            {/* Status */}
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                select
                label="Order Status"
                name="status"
                value={formData.status}
                onChange={handleChange}
              >
                <MenuItem value="Pending">
                  ⏳ Pending
                </MenuItem>

                <MenuItem value="Preparing">
                  👨‍🍳 Preparing
                </MenuItem>

                <MenuItem value="Ready">
                  🔔 Ready
                </MenuItem>

                <MenuItem value="Served">
                  ✅ Served
                </MenuItem>

                <MenuItem value="Cancelled">
                  ❌ Cancelled
                </MenuItem>
              </TextField>
            </Grid>

            {/* Instructions */}
            <Grid item xs={12}>
              <TextField
                fullWidth
                multiline
                rows={2}
                label="Special Instructions"
                name="specialInstructions"
                value={formData.specialInstructions}
                onChange={handleChange}
                placeholder="Any special requests..."
              />
            </Grid>

            {/* Summary */}
            {selectedMenuItem && (
              <Grid item xs={12}>
                <Box
                  sx={{
                    p: 2,
                    background:
                      "linear-gradient(135deg, #E8F5E8 0%, #F1F8E9 100%)",
                    borderRadius: 2,
                    border: "2px solid #4CAF50",
                  }}
                >
                  <Typography
                    variant="h6"
                    gutterBottom
                    sx={{
                      fontWeight: 700,
                      color: "#2E7D32",
                    }}
                  >
                    🧾 Order Summary
                  </Typography>

                  <Grid container spacing={1}>
                    <Grid item xs={6}>
                      <Typography variant="body2">
                        Item:
                      </Typography>
                    </Grid>

                    <Grid item xs={6}>
                      <Typography fontWeight="600">
                        {formData.itemName}
                      </Typography>
                    </Grid>

                    <Grid item xs={6}>
                      <Typography variant="body2">
                        Quantity:
                      </Typography>
                    </Grid>

                    <Grid item xs={6}>
                      <Typography fontWeight="600">
                        {formData.quantity}
                      </Typography>
                    </Grid>

                    <Grid item xs={6}>
                      <Typography variant="body2">
                        Unit Price:
                      </Typography>
                    </Grid>

                    <Grid item xs={6}>
                      <Typography fontWeight="600">
                        ₹{formData.price}
                      </Typography>
                    </Grid>

                    <Grid item xs={6}>
                      <Typography
                        sx={{
                          fontSize: "1.1rem",
                          fontWeight: 700,
                        }}
                      >
                        Total Amount:
                      </Typography>
                    </Grid>

                    <Grid item xs={6}>
                      <Typography
                        variant="h6"
                        sx={{
                          color: "#2E7D32",
                          fontWeight: 800,
                        }}
                      >
                        ₹{totalPrice}
                      </Typography>
                    </Grid>
                  </Grid>
                </Box>
              </Grid>
            )}
          </Grid>
        </form>
      </DialogContent>

      <DialogActions sx={{ p: 3, gap: 1 }}>
        <Button
          onClick={onClose}
          variant="outlined"
          size="large"
          sx={{ borderRadius: 2 }}
        >
          Cancel
        </Button>

        <Button
          onClick={handleSubmit}
          variant="contained"
          size="large"
          disabled={!formData.itemName}
          sx={{
            background:
              "linear-gradient(135deg, #2E7D32 0%, #4CAF50 100%)",
            borderRadius: 2,
            fontWeight: 700,
            "&:hover": {
              background:
                "linear-gradient(135deg, #1B5E20 0%, #2E7D32 100%)",
            },
          }}
        >
          {token ? "Update Order" : "Create Order"}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

/* =========================================================
   MAIN APP
========================================================= */

function App() {
  const [user, setUser] = useState(() => {
    const savedUser = localStorage.getItem("user");

    try {
      return savedUser ? JSON.parse(savedUser) : null;
    } catch (error) {
      console.error("Invalid saved user:", error);
      localStorage.removeItem("user");
      return null;
    }
  });

  const [tokens, setTokens] = useState([]);
  const [editingToken, setEditingToken] = useState(null);
  const [formOpen, setFormOpen] = useState(false);
  const [loading, setLoading] = useState(true);

  /* =======================================================
     RESTORE JWT
  ======================================================= */

  useEffect(() => {
    const token = localStorage.getItem("token");

    if (token) {
      axios.defaults.headers.common[
        "Authorization"
      ] = `Bearer ${token}`;
    }
  }, []);

  /* =======================================================
     LOGIN
  ======================================================= */

  const handleLogin = (loggedInUser) => {
    setUser(loggedInUser);

    localStorage.setItem(
      "user",
      JSON.stringify(loggedInUser)
    );
  };

  /* =======================================================
     LOGOUT
  ======================================================= */

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("user");

    delete axios.defaults.headers.common[
      "Authorization"
    ];

    setUser(null);
    setTokens([]);
  };

  /* =======================================================
     FETCH TOKENS
  ======================================================= */

  useEffect(() => {
    if (user) {
      fetchTokens();
    }
  }, [user]);

  const fetchTokens = async () => {
    try {
      setLoading(true);

      const response = await axios.get("/api/tokens");

      setTokens(response.data);
    } catch (error) {
      console.error(
        "Error fetching tokens:",
        error
      );
    } finally {
      setLoading(false);
    }
  };

  /* =======================================================
     CREATE TOKEN
  ======================================================= */

  const createToken = async (tokenData) => {
    try {
      await axios.post(
        "/api/tokens",
        tokenData
      );

      await fetchTokens();

      setFormOpen(false);
    } catch (error) {
      console.error(
        "Error creating token:",
        error
      );
    }
  };

  /* =======================================================
     UPDATE TOKEN
  ======================================================= */

  const updateToken = async (
    id,
    tokenData
  ) => {
    try {
      await axios.put(
        `/api/tokens/${id}`,
        tokenData
      );

      await fetchTokens();

      setFormOpen(false);
      setEditingToken(null);
    } catch (error) {
      console.error(
        "Error updating token:",
        error
      );
    }
  };

  /* =======================================================
     DELETE TOKEN
  ======================================================= */

  const deleteToken = async (id) => {
    try {
      await axios.delete(
        `/api/tokens/${id}`
      );

      await fetchTokens();
    } catch (error) {
      console.error(
        "Error deleting token:",
        error
      );
    }
  };

  /* =======================================================
     UPDATE STATUS
  ======================================================= */

  const updateTokenStatus = async (
    id,
    status
  ) => {
    try {
      await axios.patch(
        `/api/tokens/${id}/status`,
        { status }
      );

      await fetchTokens();
    } catch (error) {
      console.error(
        "Error updating token status:",
        error
      );
    }
  };

  /* =======================================================
     EDIT TOKEN
  ======================================================= */

  const handleEdit = (token) => {
    setEditingToken(token);
    setFormOpen(true);
  };

  /* =======================================================
     CLOSE FORM
  ======================================================= */

  const handleFormClose = () => {
    setFormOpen(false);
    setEditingToken(null);
  };

  /* =======================================================
     ROLE ROUTING

     IMPORTANT:
     Keep this block INSIDE App().
  ======================================================= */

  if (!user) {
    return <AuthPage onLogin={handleLogin} />;
  }

  if (user.role === "user") {
    return (
      <UserDashboard
        user={user}
        onLogout={handleLogout}
      />
    );
  }

  if (user.role === "staff") {
    return (
      <StaffDashboard
        user={user}
        onLogout={handleLogout}
      />
    );
  }

  if (user.role === "admin") {
    return (
      <AdminDashboard
        user={user}
        onLogout={handleLogout}
      />
    );
  }

  /* =======================================================
     FALLBACK MANAGER UI
  ======================================================= */

  const totalOrders = tokens.length;

  const pendingOrders = tokens.filter(
    (token) => token.status === "Pending"
  ).length;

  const preparingOrders = tokens.filter(
    (token) => token.status === "Preparing"
  ).length;

  const readyOrders = tokens.filter(
    (token) => token.status === "Ready"
  ).length;

  const servedOrders = tokens.filter(
    (token) => token.status === "Served"
  ).length;

  const totalRevenue = tokens.reduce(
    (sum, token) =>
      sum +
      Number(token.price || 0) *
        Number(token.quantity || 1),
    0
  );

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />

      {/* =================================================
          BACKGROUND
      ================================================= */}

      <div
        style={{
          position: "fixed",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          pointerEvents: "none",
          zIndex: -1,
          overflow: "hidden",
        }}
      >
        <div
          style={{
            position: "absolute",
            width: "200px",
            height: "200px",
            borderRadius: "50%",
            background:
              "linear-gradient(135deg, rgba(46,125,50,0.1) 0%, rgba(76,175,80,0.05) 100%)",
            top: "10%",
            left: "5%",
            animation:
              "float 6s ease-in-out infinite",
          }}
        />

        <div
          style={{
            position: "absolute",
            width: "150px",
            height: "150px",
            borderRadius: "50%",
            background:
              "linear-gradient(135deg, rgba(255,152,0,0.1) 0%, rgba(255,183,77,0.05) 100%)",
            top: "60%",
            right: "10%",
            animation:
              "float 6s ease-in-out infinite 2s",
          }}
        />
      </div>

      {/* =================================================
          HEADER
      ================================================= */}

      <AppBar
        position="static"
        sx={{
          background:
            "linear-gradient(135deg, #2E7D32 0%, #4CAF50 100%)",
          boxShadow:
            "0 4px 20px rgba(46,125,50,0.3)",
        }}
      >
        <Toolbar>
          <RestaurantIcon
            sx={{
              mr: 2,
              fontSize: 32,
            }}
          />

          <Typography
            variant="h4"
            component="div"
            sx={{
              flexGrow: 1,
              fontWeight: 800,
            }}
          >
            🍽️ CanteenPro Manager
          </Typography>

          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              gap: 2,
            }}
          >
            <Box sx={{ textAlign: "right" }}>
              <Typography
                variant="body2"
                sx={{ opacity: 0.9 }}
              >
                Welcome, {user.name}
              </Typography>

              <Typography
                variant="caption"
                sx={{ opacity: 0.8 }}
              >
                {user.role.toUpperCase()}
              </Typography>
            </Box>

            <Button
              onClick={handleLogout}
              variant="outlined"
              sx={{
                color: "white",
                borderColor:
                  "rgba(255,255,255,0.7)",
                fontWeight: 700,
                "&:hover": {
                  borderColor: "white",
                  backgroundColor:
                    "rgba(255,255,255,0.1)",
                },
              }}
            >
              Logout
            </Button>
          </Box>
        </Toolbar>
      </AppBar>

      {/* =================================================
          MAIN CONTAINER
      ================================================= */}

      <Container
        maxWidth="xl"
        sx={{
          mt: 4,
          mb: 4,
          position: "relative",
        }}
      >
        {/* =================================================
            STATISTICS
        ================================================= */}

        <Box
          sx={{
            mb: 4,
            p: 3,
            background:
              "linear-gradient(135deg, #ffffff 0%, #f8f9fa 100%)",
            borderRadius: 3,
            boxShadow:
              "0 4px 20px rgba(0,0,0,0.1)",
            border: "1px solid #e0e0e0",
          }}
        >
          <Typography
            variant="h5"
            gutterBottom
            sx={{
              fontWeight: 700,
              color: "#2E7D32",
            }}
          >
            📊 Live Dashboard
          </Typography>

          <Grid container spacing={2}>
            <Grid item xs={6} sm={3}>
              <Box
                sx={{
                  textAlign: "center",
                  p: 2,
                }}
              >
                <Typography
                  variant="h3"
                  color="primary"
                  sx={{ fontWeight: 800 }}
                >
                  {totalOrders}
                </Typography>

                <Typography
                  variant="body2"
                  sx={{ fontWeight: 600 }}
                >
                  Total Orders
                </Typography>
              </Box>
            </Grid>

            <Grid item xs={6} sm={3}>
              <Box
                sx={{
                  textAlign: "center",
                  p: 2,
                }}
              >
                <Typography
                  variant="h3"
                  color="warning.main"
                  sx={{ fontWeight: 800 }}
                >
                  {pendingOrders}
                </Typography>

                <Typography
                  variant="body2"
                  sx={{ fontWeight: 600 }}
                >
                  Pending
                </Typography>
              </Box>
            </Grid>

            <Grid item xs={6} sm={3}>
              <Box
                sx={{
                  textAlign: "center",
                  p: 2,
                }}
              >
                <Typography
                  variant="h3"
                  color="info.main"
                  sx={{ fontWeight: 800 }}
                >
                  {preparingOrders}
                </Typography>

                <Typography
                  variant="body2"
                  sx={{ fontWeight: 600 }}
                >
                  Preparing
                </Typography>
              </Box>
            </Grid>

            <Grid item xs={6} sm={3}>
              <Box
                sx={{
                  textAlign: "center",
                  p: 2,
                }}
              >
                <Typography
                  variant="h3"
                  color="secondary"
                  sx={{ fontWeight: 800 }}
                >
                  {readyOrders}
                </Typography>

                <Typography
                  variant="body2"
                  sx={{ fontWeight: 600 }}
                >
                  Ready
                </Typography>
              </Box>
            </Grid>

            <Grid item xs={6} sm={3}>
              <Box
                sx={{
                  textAlign: "center",
                  p: 2,
                }}
              >
                <Typography
                  variant="h3"
                  color="success.main"
                  sx={{ fontWeight: 800 }}
                >
                  {servedOrders}
                </Typography>

                <Typography
                  variant="body2"
                  sx={{ fontWeight: 600 }}
                >
                  Served
                </Typography>
              </Box>
            </Grid>
          </Grid>

          <Box
            sx={{
              mt: 2,
              textAlign: "center",
            }}
          >
            <Typography
              variant="h6"
              sx={{
                color: "#2E7D32",
                fontWeight: 700,
              }}
            >
              Total Revenue: ₹{totalRevenue}
            </Typography>
          </Box>
        </Box>

        {/* =================================================
            LOADING
        ================================================= */}

        {loading && (
          <LinearProgress
            sx={{
              mb: 2,
              height: 6,
              borderRadius: 3,
            }}
          />
        )}

        {/* =================================================
            HEADER + NEW ORDER
        ================================================= */}

        <Box
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            mb: 4,
            p: 3,
            background:
              "linear-gradient(135deg, #ffffff 0%, #f8f9fa 100%)",
            borderRadius: 3,
            boxShadow:
              "0 4px 15px rgba(0,0,0,0.1)",
          }}
        >
          <Box>
            <Typography
              variant="h4"
              sx={{
                fontWeight: 800,
                color: "#2E7D32",
              }}
            >
              🎫 Active Food Orders
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ mt: 1 }}
            >
              Manage all customer orders
              efficiently
            </Typography>
          </Box>

          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={() => setFormOpen(true)}
            sx={{
              background:
                "linear-gradient(135deg, #2E7D32 0%, #4CAF50 100%)",
              px: 4,
              py: 1.5,
              borderRadius: 3,
              fontWeight: 700,
              fontSize: "1.1rem",
              "&:hover": {
                background:
                  "linear-gradient(135deg, #1B5E20 0%, #2E7D32 100%)",
                transform: "translateY(-2px)",
              },
              transition: "all 0.3s ease",
            }}
          >
            New Order
          </Button>
        </Box>

        {/* =================================================
            ORDERS GRID
        ================================================= */}

        <Grid container spacing={3}>
          {tokens.map((token) => (
            <Grid
              item
              xs={12}
              sm={6}
              md={4}
              lg={3}
              key={token._id}
            >
              <TokenCard
                token={token}
                onEdit={handleEdit}
                onDelete={deleteToken}
                onStatusUpdate={
                  updateTokenStatus
                }
              />
            </Grid>
          ))}

          {tokens.length === 0 && !loading && (
            <Grid item xs={12}>
              <Box
                sx={{
                  textAlign: "center",
                  py: 8,
                  background:
                    "linear-gradient(135deg, #ffffff 0%, #f8f9fa 100%)",
                  borderRadius: 3,
                  boxShadow:
                    "0 4px 15px rgba(0,0,0,0.1)",
                }}
              >
                <RestaurantIcon
                  sx={{
                    fontSize: 80,
                    color: "#e0e0e0",
                    mb: 2,
                  }}
                />

                <Typography
                  variant="h5"
                  color="text.secondary"
                  gutterBottom
                >
                  No active orders yet
                </Typography>

                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{
                    mt: 1,
                    mb: 3,
                  }}
                >
                  Create your first food order
                  to get started
                </Typography>

                <Button
                  variant="contained"
                  startIcon={<AddIcon />}
                  onClick={() =>
                    setFormOpen(true)
                  }
                  sx={{
                    background:
                      "linear-gradient(135deg, #2E7D32 0%, #4CAF50 100%)",
                    px: 4,
                    py: 1.5,
                    borderRadius: 3,
                    fontWeight: 700,
                    "&:hover": {
                      background:
                        "linear-gradient(135deg, #1B5E20 0%, #2E7D32 100%)",
                    },
                  }}
                >
                  Create First Order
                </Button>
              </Box>
            </Grid>
          )}
        </Grid>

        {/* =================================================
            FLOATING BUTTON
        ================================================= */}

        <Fab
          color="primary"
          aria-label="add"
          onClick={() => setFormOpen(true)}
          sx={{
            position: "fixed",
            bottom: 24,
            right: 24,
            background:
              "linear-gradient(135deg, #2E7D32 0%, #4CAF50 100%)",
            width: 64,
            height: 64,
            "&:hover": {
              background:
                "linear-gradient(135deg, #1B5E20 0%, #2E7D32 100%)",
              transform: "scale(1.1)",
            },
            transition: "all 0.3s ease",
            boxShadow:
              "0 8px 25px rgba(46,125,50,0.3)",
          }}
        >
          <AddIcon sx={{ fontSize: 30 }} />
        </Fab>

        {/* =================================================
            TOKEN FORM
        ================================================= */}

        <TokenForm
          open={formOpen}
          token={editingToken}
          onCreate={createToken}
          onUpdate={updateToken}
          onClose={handleFormClose}
        />
      </Container>

      {/* =================================================
          FLOATING ANIMATION
      ================================================= */}

      <style>
        {`
          @keyframes float {
            0%, 100% {
              transform: translateY(0px) rotate(0deg);
            }

            50% {
              transform: translateY(-20px) rotate(180deg);
            }
          }
        `}
      </style>
    </ThemeProvider>
  );
}

export default App;
